/**
 * Generate `src/Cloudflare/AI/EvalEffectRuntime.generated.ts` — the
 * effect runtime that `Cloudflare.AI.EvalWorkerLoader` ships into
 * dynamically loaded Worker isolates so `AI.CodeModeEffect` programs
 * can run there.
 *
 * The output is ONE self-contained ESM module bundling every stable
 * top-level effect module (rolldown: browser platform, tree-shaken,
 * minified — ~763KB / ~237KB gzip), exported as a string constant.
 * The generated file is gitignored; it is (re)built by:
 *
 * - `bun i` at the repo root (postinstall), so fresh clones type-check
 * - `bun run build` in packages/alchemy, so `lib/` always carries it
 * - `bun generate:eval-runtime` by hand after bumping `effect`
 *
 * `--check` verifies the generated file matches the installed effect
 * version without rewriting it (CI drift guard).
 */
import { readdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { gzipSync } from "node:zlib";
import { rolldown } from "rolldown";

const require = createRequire(import.meta.url);
const packageRoot = resolve(import.meta.dirname, "..");
const outFile = join(
  packageRoot,
  "src/Cloudflare/AI/EvalEffectRuntime.generated.ts",
);

const effectPackage = require.resolve("effect/package.json", {
  paths: [packageRoot],
});
const effectVersion = (
  JSON.parse(readFileSync(effectPackage, "utf8")) as { version: string }
).version;

if (process.argv.includes("--check")) {
  const current = existsSync(outFile) ? readFileSync(outFile, "utf8") : "";
  if (!current.includes(`EFFECT_RUNTIME_VERSION = "${effectVersion}"`)) {
    console.error(
      `EvalEffectRuntime.generated.ts is missing or was built against a different effect version ` +
        `(installed: ${effectVersion}) — run \`bun generate:eval-runtime\` in packages/alchemy.`,
    );
    process.exit(1);
  }
  console.log(
    `EvalEffectRuntime.generated.ts is current (effect@${effectVersion})`,
  );
  process.exit(0);
}

// Every stable top-level module: the PascalCase entries of effect/dist.
// Model programs are unknown ahead of time, so the unit of curation is
// the MODULE (ship each chosen module's full public surface); unstable/*
// and testing/* stay out.
const dist = join(dirname(effectPackage), "dist");
const modules = readdirSync(dist)
  .filter((file) => file.endsWith(".js"))
  .map((file) => file.slice(0, -3))
  .filter((name) => /^[A-Z]/.test(name))
  .sort();

const entry = modules
  .map((name) => `export * as ${name} from "effect/${name}";`)
  .join("\n");
const entryFile = join(packageRoot, ".eval-effect-runtime-entry.ts");
writeFileSync(entryFile, entry);

try {
  const bundle = await rolldown({
    input: entryFile,
    platform: "browser",
    treeshake: true,
  });
  const { output } = await bundle.generate({ format: "esm", minify: true });
  const code = output
    .map((chunk) => ("code" in chunk ? chunk.code : ""))
    .join("");
  const gzip = gzipSync(Buffer.from(code), { level: 9 }).length;

  writeFileSync(
    outFile,
    [
      `// AUTO-GENERATED by scripts/generate-eval-effect-runtime.ts — DO NOT EDIT.`,
      `// effect@${effectVersion} — ${modules.length} modules, ${(code.length / 1024).toFixed(0)}KB minified (${(gzip / 1024).toFixed(0)}KB gzip).`,
      `// Gitignored; regenerated by root postinstall and packages/alchemy build.`,
      ``,
      `/** The effect version this runtime was bundled from. */`,
      `export const EFFECT_RUNTIME_VERSION = ${JSON.stringify(effectVersion)};`,
      ``,
      `/** The stable top-level effect modules exported by the runtime. */`,
      `export const EFFECT_RUNTIME_MODULES: ReadonlyArray<string> = ${JSON.stringify(modules)};`,
      ``,
      `/**`,
      ` * One self-contained ESM module bundling every stable top-level`,
      ` * effect module — the \`"effect.js"\` entry of the dynamic worker's`,
      ` * module map, so codemode programs can \`import { Effect } from "./effect.js"\`.`,
      ` */`,
      `export const EFFECT_RUNTIME: string = ${JSON.stringify(code)};`,
      ``,
    ].join("\n"),
  );
  console.log(
    `wrote ${outFile} (effect@${effectVersion}, ${modules.length} modules, ${(code.length / 1024).toFixed(0)}KB / ${(gzip / 1024).toFixed(0)}KB gzip)`,
  );
} finally {
  const { rmSync } = await import("node:fs");
  rmSync(entryFile, { force: true });
}
